/**
 * Report Viewer Page
 * Lists reports generated by the Firehorse Report Engine.
 * Supports filtering by type, download via API, and preview modal placeholder.
 * Report metadata is fetched from Supabase.
 */

import { useEffect, useState, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../lib/supabase';

type ReportType = 'Carbon' | 'Compliance' | 'Financial';
type ReportStatus = 'complete' | 'generating' | 'failed';

interface Report {
  id: string;
  title: string;
  type: ReportType;
  status: ReportStatus;
  created_at: string;
  file_size_kb: number;
  project_name: string;
  period: string;
}

const REPORT_TYPE_STYLES: Record<ReportType, string> = {
  Carbon: 'bg-emerald-900/40 text-emerald-300 border-emerald-700/50',
  Compliance: 'bg-blue-900/40 text-blue-300 border-blue-700/50',
  Financial: 'bg-amber-900/40 text-amber-300 border-amber-700/50',
};

const STATUS_STYLES: Record<ReportStatus, string> = {
  complete: 'bg-green-900/40 text-green-300',
  generating: 'bg-yellow-900/40 text-yellow-300',
  failed: 'bg-red-900/40 text-red-300',
};

const STATUS_LABELS: Record<ReportStatus, string> = {
  complete: 'Complete',
  generating: 'Generating...',
  failed: 'Failed',
};

const API_BASE = import.meta.env.VITE_API_URL || '';

export function ReportViewerPage() {
  const navigate = useNavigate();
  const [reports, setReports] = useState<Report[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterType, setFilterType] = useState<ReportType | 'All'>('All');
  const [previewReport, setPreviewReport] = useState<Report | null>(null);

  useEffect(() => {
    async function loadReports() {
      setLoading(true);

      const { data, error } = await supabase
        .from('reports')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) {
        console.error('Error fetching reports:', error);
        // Provide demo data when table doesn't exist
        setReports(getDemoReports());
        setLoading(false);
        return;
      }

      if (data && data.length > 0) {
        const mapped: Report[] = data.map((r) => ({
          id: r.id,
          title: r.title || r.report_type || 'Untitled Report',
          type: mapReportType(r.report_type),
          status: (r.status as ReportStatus) || 'complete',
          created_at: r.created_at || r.generated_at || new Date().toISOString(),
          file_size_kb: r.file_size_kb || 0,
          project_name: r.project_name || 'Portfolio',
          period: r.period || 'Q4 2025',
        }));
        setReports(mapped);
      } else {
        setReports(getDemoReports());
      }

      setLoading(false);
    }

    loadReports();
  }, []);

  const filteredReports = filterType === 'All'
    ? reports
    : reports.filter((r) => r.type === filterType);

  const handleDownload = useCallback((reportId: string) => {
    const url = `${API_BASE}/api/v1/reports/${reportId}/download`;
    window.open(url, '_blank', 'noopener,noreferrer');
  }, []);

  const handlePreview = useCallback((report: Report) => {
    setPreviewReport(report);
  }, []);

  const closePreview = useCallback(() => {
    setPreviewReport(null);
  }, []);

  if (loading) {
    return (
      <div className="min-h-dvh bg-background text-foreground p-6">
        <div className="max-w-7xl mx-auto space-y-6">
          <div className="h-8 bg-fg-muted/10 rounded w-48 animate-pulse" />
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {[...Array(6)].map((_, i) => (
              <div key={i} className="h-48 bg-fg-muted/10 rounded-xl animate-pulse" />
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-dvh bg-background text-foreground p-6">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Page Header */}
        <div className="flex items-center justify-between flex-wrap gap-4">
          <div>
            <h1 className="text-2xl font-bold text-white">Report Viewer</h1>
            <p className="text-sm text-fg-muted mt-1">Firehorse Report Engine &middot; {reports.length} reports</p>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => navigate('/templates')}
              className="px-3 py-1.5 rounded-lg text-xs font-medium bg-fg-muted/20 text-fg-muted hover:bg-fg-muted"
            >
              Edit Templates
            </button>
            {(['All', 'Carbon', 'Compliance', 'Financial'] as const).map((type) => (
              <button
                key={type}
                onClick={() => setFilterType(type)}
                className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                  filterType === type
                    ? 'bg-primary-600 text-white'
                    : 'bg-fg-muted/10 text-fg-muted hover:bg-fg-muted/20'
                }`}
              >
                {type}
              </button>
            ))}
          </div>
        </div>

        {/* Report Cards Grid */}
        {filteredReports.length === 0 ? (
          <div className="bg-surface border border-border rounded-xl p-12 text-center">
            <p className="text-fg-muted">No reports found for the selected filter.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredReports.map((report) => (
              <div
                key={report.id}
                className="bg-surface border border-border rounded-xl p-5 flex flex-col justify-between hover:border-border transition-colors"
              >
                {/* Card Header */}
                <div>
                  <div className="flex items-start justify-between mb-3">
                    <span className={`text-xs font-medium px-2 py-0.5 rounded border ${REPORT_TYPE_STYLES[report.type]}`}>
                      {report.type}
                    </span>
                    <span className={`text-xs font-medium px-2 py-0.5 rounded ${STATUS_STYLES[report.status]}`}>
                      {STATUS_LABELS[report.status]}
                    </span>
                  </div>

                  <h3 className="text-base font-semibold text-white mb-1 line-clamp-2">{report.title}</h3>
                  <p className="text-xs text-fg-muted">{report.project_name} &middot; {report.period}</p>
                </div>

                {/* Card Footer */}
                <div className="mt-4 pt-3 border-t border-border">
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-xs text-fg-muted">
                      {new Date(report.created_at).toLocaleDateString('en-GB', {
                        day: 'numeric',
                        month: 'short',
                        year: 'numeric',
                      })}
                    </span>
                    {report.file_size_kb > 0 && (
                      <span className="text-xs text-fg-muted">{report.file_size_kb} KB</span>
                    )}
                  </div>

                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => handlePreview(report)}
                      className="flex-1 px-3 py-1.5 text-xs font-medium text-fg-muted bg-fg-muted/10 rounded-lg hover:bg-fg-muted/20 transition-colors"
                    >
                      Preview
                    </button>
                    <button
                      onClick={() => handleDownload(report.id)}
                      disabled={report.status !== 'complete'}
                      className="flex-1 px-3 py-1.5 text-xs font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
                    >
                      Download
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Preview Modal — PDF iframe or HTML fallback */}
        {previewReport && (
          <ReportPreviewModal
            report={previewReport}
            onClose={closePreview}
            onDownload={handleDownload}
          />
        )}
      </div>
    </div>
  );
}

// Helpers

function mapReportType(raw: string | undefined): ReportType {
  if (!raw) return 'Carbon';
  const normalized = raw.toLowerCase();
  if (normalized.includes('compliance') || normalized.includes('csrd') || normalized.includes('epbd')) return 'Compliance';
  if (normalized.includes('financial') || normalized.includes('cost')) return 'Financial';
  return 'Carbon';
}

/**
 * Fetch a signed URL for the report PDF stored in Supabase Storage.
 * Bucket: "reports", path: "<reportId>.pdf"
 * Falls back to the API download endpoint if storage is unavailable.
 */
async function getReportPreviewUrl(reportId: string): Promise<{ url: string; type: 'pdf' | 'fallback' }> {
  try {
    const { data, error } = await supabase.storage
      .from('reports')
      .createSignedUrl(`${reportId}.pdf`, 300); // 5 min expiry

    if (!error && data?.signedUrl) {
      return { url: data.signedUrl, type: 'pdf' };
    }
  } catch {
    // Storage not available — fall through
  }

  // Fallback: use the API download endpoint (may trigger download instead of preview)
  const apiUrl = `${API_BASE}/api/v1/reports/${reportId}/download`;
  return { url: apiUrl, type: 'fallback' };
}

function ReportPreviewModal({
  report,
  onClose,
  onDownload,
}: {
  report: Report;
  onClose: () => void;
  onDownload: (id: string) => void;
}) {
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [previewType, setPreviewType] = useState<'pdf' | 'fallback' | 'loading'>('loading');
  const iframeRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    let cancelled = false;

    if (report.status !== 'complete') {
      setPreviewType('fallback');
      return;
    }

    getReportPreviewUrl(report.id).then(({ url, type }) => {
      if (!cancelled) {
        setPreviewUrl(url);
        setPreviewType(type);
      }
    });

    return () => { cancelled = true; };
  }, [report.id, report.status]);

  // Close on Escape
  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [onClose]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="bg-surface border border-border rounded-xl w-full max-w-4xl mx-4 max-h-[90vh] flex flex-col">
        {/* Modal Header */}
        <div className="flex items-center justify-between p-5 border-b border-border">
          <div>
            <h2 className="text-lg font-semibold text-white">{report.title}</h2>
            <p className="text-xs text-fg-muted mt-0.5">
              {report.type} &middot; {report.project_name} &middot; {report.period}
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-2 text-fg-muted hover:text-white rounded-lg hover:bg-fg-muted/10 transition-colors"
            aria-label="Close preview"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* Modal Body — PDF iframe or HTML summary */}
        <div className="flex-1 overflow-hidden min-h-[400px]">
          {previewType === 'loading' && (
            <div className="flex items-center justify-center h-full">
              <div className="animate-pulse text-fg-muted text-sm">Loading preview...</div>
            </div>
          )}

          {previewType === 'pdf' && previewUrl && (
            <iframe
              ref={iframeRef}
              src={previewUrl}
              title={`Preview: ${report.title}`}
              className="w-full h-full border-0"
              style={{ minHeight: '400px' }}
            />
          )}

          {previewType === 'fallback' && (
            <div className="p-6 overflow-y-auto h-full">
              <div className="bg-fg-muted/10 rounded-lg p-6 max-w-2xl mx-auto">
                <div className="flex items-center gap-3 mb-4">
                  <div className={`w-3 h-3 rounded-full ${
                    report.status === 'complete' ? 'bg-green-400' :
                    report.status === 'generating' ? 'bg-yellow-400 animate-pulse' :
                    'bg-red-400'
                  }`} />
                  <span className="text-sm text-fg-muted font-medium">{STATUS_LABELS[report.status]}</span>
                </div>

                <h3 className="text-white font-semibold text-lg mb-2">{report.title}</h3>

                <dl className="grid grid-cols-2 gap-x-6 gap-y-3 text-sm mt-4">
                  <div>
                    <dt className="text-fg-muted">Type</dt>
                    <dd className="text-foreground">{report.type}</dd>
                  </div>
                  <div>
                    <dt className="text-fg-muted">Project</dt>
                    <dd className="text-foreground">{report.project_name}</dd>
                  </div>
                  <div>
                    <dt className="text-fg-muted">Period</dt>
                    <dd className="text-foreground">{report.period}</dd>
                  </div>
                  <div>
                    <dt className="text-fg-muted">Generated</dt>
                    <dd className="text-foreground">
                      {new Date(report.created_at).toLocaleDateString('en-GB', {
                        day: 'numeric', month: 'short', year: 'numeric',
                      })}
                    </dd>
                  </div>
                  {report.file_size_kb > 0 && (
                    <div>
                      <dt className="text-fg-muted">File Size</dt>
                      <dd className="text-foreground">{report.file_size_kb} KB</dd>
                    </div>
                  )}
                </dl>

                {report.status !== 'complete' && (
                  <p className="text-xs text-fg-muted mt-4">
                    {report.status === 'generating'
                      ? 'This report is still being generated. Check back shortly.'
                      : 'Report generation failed. Please retry or contact support.'}
                  </p>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Modal Footer */}
        <div className="p-4 border-t border-border flex justify-end gap-2">
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm text-fg-muted bg-fg-muted/10 rounded-lg hover:bg-fg-muted/20 transition-colors"
          >
            Close
          </button>
          <button
            onClick={() => onDownload(report.id)}
            disabled={report.status !== 'complete'}
            className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
          >
            Download Report
          </button>
        </div>
      </div>
    </div>
  );
}

